describe('Async State Preservation during Browser Navigation', () => {
    beforeEach(() => {
        cy.visit('/'); // Adjust the URL to your application's entry point
    });

    it('should preserve async state when navigating away and back', () => {
        // Simulate an async operation
        cy.intercept('GET', '/api/data', { fixture: 'data.json' }).as('getData');
        cy.get('button.load-data').click(); // Assume there's a button to load data
        cy.wait('@getData');

        // Verify the async state is set
        cy.get('.data-display').should('contain', 'Expected Data');

        // Navigate away
        cy.get('a.navigate-away').click(); // Assume there's a link to navigate away
        cy.url().should('include', '/another-page');

        // Navigate back
        cy.get('a.navigate-back').click(); // Assume there's a link to navigate back
        cy.url().should('include', '/');

        // Verify the async state is still preserved
        cy.get('.data-display').should('contain', 'Expected Data');
    });

    it('should not preserve async state if the user refreshes the page', () => {
        // Simulate an async operation
        cy.intercept('GET', '/api/data', { fixture: 'data.json' }).as('getData');
        cy.get('button.load-data').click();
        cy.wait('@getData');

        // Verify the async state is set
        cy.get('.data-display').should('contain', 'Expected Data');

        // Refresh the page
        cy.reload();

        // Verify the async state is reset
        cy.get('.data-display').should('not.contain', 'Expected Data');
    });
});
